  }

  function start() {
    var roots = rootList();
    if (roots.length) bindAll();
    // 聊天/消息异步渲染：定时补绑 + DOM 观察
    timers.push(setTimeout(function () { bindAll(); }, 400));
    timers.push(setTimeout(function () { bindAll(); }, 1400));
