  const DLC_ENTRIES = [{"name":"[DLC]灵气复苏总纲与异象日程","enabled":true,"strategy":{"type":"constant"},"position":{"type":"before_character_definition","order":22},"content":"<%_ {\n/* JY_DLC_ORIGIN_BEGIN */\nconst dlcOriginDate = \"2020-09-01\";\n/* JY_DLC_ORIGIN_END */\nconst toIsoDay = (raw) => {\n  const m = String(raw || '').trim().match(/^(\\d{4})[-/年.](\\d{1,2})[-/月.](\\d{1,2})/);\n  if (!m) return null;\n  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);\n  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;\n  return Date.UTC(y, mo - 1, d);\n};\nconst startMs = toIsoDay(getvar('stat_data.剧情.灵气复苏.开启日期', { defaults: '' })) ?? toIsoDay(dlcOriginDate) ?? Date.UTC(2020, 8, 1);\nconst curDateStr = String(getvar('stat_data.世界.日期', { defaults: '' }) || dlcOriginDate);\nconst curMs = toIsoDay(curDateStr) ?? startMs;\nconst elapsedDays = Math.max(0, Math.floor((curMs - startMs) / 86400000));\nconst dayNumber = elapsedDays + 1;\nconst originLabel = String(getvar('stat_data.剧情.灵气复苏.开启日期', { defaults: '' }) || dlcOriginDate);\nconst playerClass = String(getvar('stat_data.主角.班级', { defaults: '' }) || '高二重点班');\nconst realm = String(getvar('stat_data.主角.修行.境界', { defaults: '' }) || '未引气（凡躯）');\nconst stageName = elapsedDays <= 10 ? '微兆潜龙期' : elapsedDays <= 25 ? '古武抬头期' : elapsedDays <= 45 ? '龙眼破禁期' : '潜龙秘序期';\n_%>\n[都市修仙DLC：华夏潜龙与灵气复苏总纲｜开启日：<%= originLabel %>｜第 <%= dayNumber %> 日（<%= stageName %>）｜主角境界：<%= realm %>]\n\n华夏龙脉与暨阳暗局:\n  潜龙归元窍: 暨阳表象是浙中百万人口强县与工商市井，实则地处华夏南干龙余脉入越折返处的一座沉睡主窍——「越中潜龙·归元眼」，北承会稽余脉、东抱老鹰山、南接浦阳/浣江水势。千年之前古贤以镇山大阵敛藏地脉不外泄，使此城龙气内蕴而非外炫：西施故里历代人杰地灵、山下湖水脉凝出「澹珠记」蕴灵古珠、老城与万风地库古宅旧器历久不腐，皆源于地底深藏的一缕龙脉清气。\n  太微云岫古宗兴衰: 数百年前老鹰山曾是越地声势赫赫的「太微云岫宗」祖庭，主峰剑阵吞吐云气、亭池聚灵供千修问道；自明中叶起天地灵机大潮渐退，地球堕入末法枯竭，云岫宗护山大阵自封沉入山腹地底，仅余山腰听风亭残基、屋檐「镇风青铜铎」、枯井荒坛与守灯执事周伯苦撑末世。\n\n修行契约与无上限阶梯（不锁死境界上限）:\n  灵根稀缺与秘而不宣铁律: 灵气复苏绝非全民普及、人人皆可修仙，真正先天带灵根、能引真气入脉问道者万里无一；古武站桩纵能强身延寿几年，终究仍属百年凡胎。官方与隐门均严守绝密准则——**永远不向普通民众与校园公布灵气真相，绝不搞公开修仙班或大众科普**，仅在暗处秘密核验并单线接触极少数显露灵根或顶尖天赋之人。\n  同源并流与开放破境: 古武「锻骨强身→明劲→暗劲→化劲宗师→先天通玄」与仙途「引气感灵→炼气（初/中/后/大圆满）→筑基→金丹→元婴→化神及之上」不设僵化时间或境界封顶。只要得周伯授艺、老鹰山龙眼共鸣、圣女云清晏点拨合参、或借「澹珠记」灵珠与「万风地库」旧器淬炼契机，皆可实打实破境飞跃；仅严格守住「跨大境须有感悟、机缘或劫难代价，绝不空口白送」的分寸。\n\n红尘、长生与「仙凡两隔」之问:\n  凡骨常人与真正的时空割裂: 正因灵根万中无一且世俗绝不公开普及，原有七位女主（苏晓樯、温书语、沈幼楚、许念安、陈芷汀、慕佳芊、虞淑婉）默认皆系**没有修仙灵根的凡尘俗骨**（偶触澹珠微温或听过异闻，不等于具备仙途命格）。绝大部分人终究按凡俗尺度读书、工作、老去。\n  圣女与诸女的道心张力: 一旦主角随云清晏迈过炼气、踏入筑基乃至金丹元婴长生尺度，高三试卷与小城三鲜打面依然真切，却在寿元与灵觉纵深里显出近乎残忍的短暂——若选择与云清晏结为道侣同参大道，便须直面毫无退路的「仙凡两隔」之痛：替无灵根的凡人女伴逆天洗髓续命不仅天材地宝难觅且逆天代价极沉，她们也未必愿意割舍现世灯火去赴孤冷长途；若不渡之，只能眼看故人青丝雪落、百年凋零。问道是化作冷石俯瞰苍生，还是带着这份重逾千钧的牵挂去护眼下人间，须由每一次选择作答。\n\n当前日历阶段异象（表层永远维持现代日常，仅里世界暗涌 <%= stageName %> 变化）:\n<%_ if (elapsedDays <= 10) { _%>\n  - 第一阶段·微兆潜龙期（第1～10天）：老鹰山主峰与浦阳江面夜间偶现几秒低空青白色微晕；城内负氧离子读数与局部地磁偶发微小跳变，老旧调频收音机深夜偶掠十秒无法定频的风铃清音；老香樟提前落叶重萌新芽，夜间犬猫常望东南山脊低吠。气象与广播台以「逆温折光/静电扰动」解释，校园日常照常。\n  - 极少数先天感气极微者或长期站桩者，于老鹰山晨雾附近能嗅到一丝异于常氧的清冽凉气；此前被视为普通护林老人的周伯开始暗自审视山势与来客骨相。\n<%_ if (elapsedDays === 0) { _%>\n  - 启封初日伏笔：今日老鹰山潜龙窍微微一震，正在江南游历疗伤的云岫古宗圣女云清晏隔空感应到祖庭异动，已动身赶赴暨阳并凭宗门隐脉办妥次日插班借读手续——今日尚在途中未进校园，明日（第2天）起正式转入<%= playerClass %>。\n<%_ } else { _%>\n  - 云清晏入世动向：圣女云清晏已于今日抵达暨阳并作为转校生插入<%= playerClass %>，外表为病弱素净的转学少女，实则正借重点高中日常隐遁养伤并暗查龙脉主窍与主角身上气机。\n<%_ } _%>\n<%_ } else if (elapsedDays <= 25) { _%>\n  - 第二阶段·古武抬头与灵潮涌动期（第11～25天）：暨阳清晨水雾含润甘气息，老鹰山听风亭一带深吸已有清神微效；全国暗中流传的旧武传人与少数长期吐纳者丹田发热、旧伤悄然松动；「澹珠记」极少数老珠与「万风地库」沉睡古器偶在深夜泛起微温。\n  - 隐秘管控启动：医院极少数无器质病变的「手心发暖/夜视微增」门诊记录被隐秘检索系统悄然标记并脱敏归档，大众媒体只字不提；古玩行与旧武圈仅在私下暗中寻访山野真器，普通中学生活一如既往。\n<%_ } else if (elapsedDays <= 45) { _%>\n  - 第三阶段·龙眼破禁与暗线摸排期（第26～45天）：老鹰山后山枯井与潜龙支脉雾霭常聚不散、雷雨夜弧光偶见绕峰偏折；少数真灵根觉醒者或深厚古武者在无人处可展御风借力、劲透枯木或内息疗伤等真异能。\n  - 秘密接触而非公开：国家「特种气象与非典型样本调查组（隐秘特调）」只穿便装悄悄核对高异常个体，**严禁向校方师生或公众披露半字**，只在私下试探、登记或暗中评估真正有灵根/极高天赋之人（如主角身怀龙脉异动）；若与云清晏或周伯深入配合，此时亦可悄悄叩开山腹沉封山门、直探祖庭机缘。\n<%_ } else { _%>\n  - 第四阶段·潜龙秘序期（第46～60+天）：都市表面依然平静得像什么都没发生过——高考复习、班群八卦、街头打面与凡人四季丝毫不变，99.9% 的普通人与同班女生依然活在纯现代时空里；唯独极小圈子的里世界正式成形——隐秘特调与少数受邀签密的天赋觉醒者暗中对接珍稀药材与任务，外地散修与隐门亦开始悄悄试探暨阳越中潜龙眼。\n  - 正因没有全员修仙的廉价奇迹，主角站在古宗传承、特调密触与红尘旧约的裂隙之上：在云清晏所代表的仙道长生与七位无灵根凡尘女孩短暂灼热的一生之间，每一步破境都伴随着真正的仙凡取舍与重量。\n<%_ } _%>\n<%_ } _%>\n","probability":100,"recursion":{"prevent_incoming":true,"prevent_outgoing":true,"delay_until":null},"effect":{"sticky":null,"cooldown":null,"delay":null}},{"name":"[DLC]老鹰山灵脉与古宗秘藏","enabled":true,"strategy":{"type":"selective","keys":["老鹰山","听风亭","旧值守屋","周伯","周守山","镇风铎","枯井","石碑","云岫宗","太微云岫宗","古宗","山门","龙脉","潜龙","灵气","吐纳","古武","澹珠","万风"],"scan_depth":2},"position":{"type":"after_character_definition","order":125},"content":"[DLC事件｜老鹰山灵脉与太微云岫古宗秘藏]\n触发背景: 当都市修仙DLC开启后，老鹰山不再只是城郊步道与退休护林屋，而是太微云岫古宗沉封山门与越中潜龙脉交汇的「听风归元窍」。\n\n宗门遗构真容:\n  听风亭（护山阵残角）: 八角青石基座实为上古「听风聚灵阵」八方乾坤柱之一，柱础苔痕下刻着导引山脉风气的云篆禁纹；灵潮涌动后，立于亭中吐纳可获事半功倍的聚灵效用。\n  镇风青铜铎（旧值守屋檐下）: 并非常人风铃，而是云岫古宗历代守山执事所持下品灵器「镇风铎」半器残件。日常凡风吹不落灰尘，唯有蕴含真气/灵识波动、或云岫直系血脉临近时方会发出直透神魂的清音震颤。\n  枯井残坛与沉封山门: 值守屋后方荒径尽头的干涸古井，井壁内侧留有历代祖师锁山封印的阵眼凹槽；逢灵潮升至中后期或集齐「镇风铎清鸣 / 图书馆三楼县志阵方位 / 周伯或云清晏印诀」时，可顺井下石阶窥见深藏山腹、半浸在一池浅碧龙脉灵泉中的太微云岫宗遗殿前阙。\n\n周伯（周守山）真身与机缘阶梯:\n  真身: 太微云岫宗外门最后一代守灯执事「周守山」，年少拜入残宗，苦守末法八十年。表面修为看似因灵竭止步养气境，实则怀有残存半步筑基道基与全套古宗外门筑基谱系，昔年亦曾在山中见过幼时随长辈闭关的云清晏。\n  授艺阶梯（不锁上限，以心性与机缘定夺）:\n    1. 固骨养气: 见主角曾帮衬老屋或已于日常练稳「松溪吐风桩」，转授正式内修真篇《太微导引术》，引其感应山风第一缕游离灵气。\n    2. 古宗秘藏与《暨阳风物补遗》: 图书馆三楼旧书库那本被视作清末游记的抄本实为云岫外门暗录；对照碑文破解听风亭阵图后，周伯可放开荒径禁制，准主角进山门前殿借用残存灵池炼体、领悟《云岫剑气残篇》或《松溪炼神桩》。\n    3. 联动旧器（澹珠记与万风地库）: 若主角携「澹珠记」蕴灵老珍珠或「万风地库」流出的带韵古木铜铁入山门灵眼，可涤尽岁尘显出微灵真质（辅助聚气疗伤），并助周伯印证「暨阳全城龙脉正在次第醒转」的判断。\n  分寸提示: 周伯重因果与道心清正，绝不强逼主角拜师或与外人厮杀，亦提醒主角切勿凭初得灵气在普通同窗面前卖弄惹来特事稽查与因果反噬。\n","probability":100,"recursion":{"prevent_incoming":true,"prevent_outgoing":true,"delay_until":null},"effect":{"sticky":null,"cooldown":null,"delay":null}},{"name":"云清晏_基础信息","enabled":true,"strategy":{"type":"constant"},"position":{"type":"after_character_definition","order":79},"content":"<%_ {\nconst toIsoDay = (raw) => {\n  const m = String(raw || '').trim().match(/^(\\d{4})[-/年.](\\d{1,2})[-/月.](\\d{1,2})/);\n  if (!m) return null;\n  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);\n  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;\n  return Date.UTC(y, mo - 1, d);\n};\nconst originStr = String(getvar('stat_data.剧情.灵气复苏.开启日期', { defaults: '' }) || '2020-09-01');\nconst curStr =